import React from 'react';

const Education = () => {
    return (
        <section>
            <h1>Education</h1>
            <ul>
                <li>School/University: [Name]</li>
                <li>Course: [Course Name]</li>
                <li>Year: [Year]</li>
            </ul>
        </section>
    );
};

export default Education;
